#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [HeatTransferCoefficient; 6] = [
        HeatTransferCoefficient::const_new(
            1234.5,
            HeatTransferCoefficientUnit::WattPerSquareMeterKelvin,
        ),
        HeatTransferCoefficient::const_new(
            1234.5,
            HeatTransferCoefficientUnit::WattPerSquareMeterCelsius,
        ),
        HeatTransferCoefficient::const_new(
            1234.5,
            HeatTransferCoefficientUnit::BtuPerHourSquareFootDegreeFahrenheit,
        ),
        HeatTransferCoefficient::const_new(
            1234.5,
            HeatTransferCoefficientUnit::BtuPerSecondSquareInchDegreeFahrenheit,
        ),
        HeatTransferCoefficient::const_new(
            1234.5,
            HeatTransferCoefficientUnit::CaloriePerHourSquareMeterDegreeCelsius,
        ),
        HeatTransferCoefficient::const_new(
            1234.5,
            HeatTransferCoefficientUnit::KilocaloriePerHourSquareMeterDegreeCelsius,
        ),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(HeatTransferCoefficientUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            HeatTransferCoefficient::new(1234.5_f64, unit)
                .as_base()
                .to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in HeatTransferCoefficientUnit::ALL {
            assert_eq!(
                HeatTransferCoefficient::const_new(v, unit)
                    .as_base()
                    .to_bits(),
                HeatTransferCoefficient::<f64>::new(v, unit)
                    .as_base()
                    .to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = HeatTransferCoefficient::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            HeatTransferCoefficient::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in HeatTransferCoefficientUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        HeatTransferCoefficient::from_base(0.0).auto_unit().unit,
        HeatTransferCoefficientUnit::WattPerSquareMeterKelvin
    );
}

